    """Test parsing a normal security requirement."""
    print("Testing parsing of normal security requirement...")

    try:
        # Create a SecurityRequirement with normal dict
        sec_req = SecurityRequirement(['test'], {"apiKey": ["read"]}, None)

        # Check attributes
        assert sec_req.name == "apiKey"
        assert sec_req.types == ["read"]

        # Check __getstate__
        state = sec_req.__getstate__()
        assert state == {"apiKey": ["read"]}

        print("SUCCESS: Normal security requirement parsing works")
        return True
